T['es_419'] = T['es']
assert len(K) == 11, len(K)
for lang, vals in T.items():
    assert len(vals) == len(K), (lang, len(vals))
    p = f'{ROOT}/{lang}.json'
    raw = open(p, encoding='utf-8').read()
    d = json.loads(raw)
    for k, v in zip(K, vals):
        d[k] = v
    s = json.dumps(d, ensure_ascii=False, indent=2) + ('\n' if raw.endswith('\n') else '')
    open(p, 'w', encoding='utf-8', newline='').write(s)
print('ok', len(T), 'languages x', len(K))
